import redis
import pickle

class UserCache:
    def __init__(self, redis_host='localhost', redis_port=6379):
        self.client = redis.Redis(host=redis_host, port=redis_port, decode_responses=False)

    def get_user(self, user_id):
        """Retrieve cached user object or return None if not cached."""
        cached = self.client.get(f'user:{user_id}')
        if cached:
            return pickle.loads(cached)
        return None

    def cache_user(self, user_id, user_obj, ttl=3600):
        """Store user object in cache with TTL in seconds."""
        serialized = pickle.dumps(user_obj)
        self.client.setex(f'user:{user_id}', ttl, serialized)

    def invalidate_user(self, user_id):
        """Remove user from cache."""
        self.client.delete(f'user:{user_id}')

# Usage
cache = UserCache()
user_data = {'id': 123, 'name': 'Alice', 'email': 'alice@example.com', 'password_hash': 'abc123...'}
cache.cache_user(123, user_data)

# Later retrieval
user = cache.get_user(123)
print(user['name'])
